using Microsoft.AspNetCore.Mvc;using RaceDay.Mvc.Services;namespace RaceDay.Mvc.Controllers;public class DashboardController(RaceApi api):Controller{public async Task<IActionResult> Index(){var role=HttpContext.Session.GetString("role");if(role==null)return RedirectToAction("Login","Account");if(role=="Participant")return RedirectToAction("MyEvents","Participant");var all=await api.Get<List<RaceEvent>>("api/events")??new();var mine=all.Where(e=>e.OrganiserId==HttpContext.Session.GetInt32("userId")).ToList();ViewBag.Events=mine;ViewBag.Upcoming=mine.Count(e=>e.EventDate>=DateTime.Today);var counts=new Dictionary<int,int>();foreach(var e in mine){var entries=await api.Get<List<Enrolment>>($"api/events/{e.EventId}/enrolments")??new();counts[e.EventId]=entries.Count;}ViewBag.EnrolmentCounts=counts;return View(mine);}}